    "CONTEST HALL" to Tr(ja = "コンテストかいじょう", fr = "la SALLE DE CONCOURS", de = "der WETTBEWERBSHALLE", it = "sala delle GARE POKéMON", es = "la SALA de CONCURSOS"),
